"@

$tsxFiles = Get-ChildItem -Path $dashDir -Recurse -Filter '*.tsx' | Where-Object { ($_.Name -notmatch '\.test\.|\.spec\.') -and ($_.FullName -notmatch 'node_modules|dist') }

$count = 0
foreach ($file in $tsxFiles) {
    $content = Get-Content $file.FullName -Raw
    
    if ($content -match "from\s+['"]lucide-react['"]") {
        $importLineIndex = -1
        $lines = $content.Split([Environment]::NewLine)
        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ($lines[$i] -match "from\s+['"]lucide-react['"]") {
                $importLineIndex = $i
                break
            }
        }
        
        if ($importLineIndex -ge 0) {
            # Remove import line and add Icons object
            $newContent = [string]::Join("", $lines[0..($importLineIndex-1)]) + $solarIconsCode
            
            # Add the rest of the content after removed import
            for ($j = $importLineIndex + 1; $j -lt $lines.Count; $j++) {
                if ($lines[$j] -match "^import|^interface|^export|^type ") {
                    $newContent += "`n" + $lines[$j]
                }
            }
            
            Set-Content $file.FullName $newContent -Encoding UTF8 -NoNewline
            Write-Host "✅ Migrated: $($file.Name)" -ForegroundColor Green
            $count++
        }
    }
}

Write-Host "`n🎉 Completed! Migrated $count files." -ForegroundColor Cyan
